```python
class Solution:
    def count(self, num1: str, num2: str, min_sum: int, max_sum: int) -> int:
        MOD = 10**9 + 7

        def digit_sum(x):
            return sum(int(digit) for digit in str(x))

        def is_good_integer(x):
            return (num1 <= x <= num2) and (min_sum <= digit_sum(x) <= max_sum)

        def count_good_integers(start, end):
            count = 0
            for x in range(start, end + 1):
                if is_good_integer(x):
                    count = (count + 1) % MOD
            return count

        num1_digits = [int(digit) for digit in str(num1)]
        num2_digits = [int(digit) for digit in str(num2)]

        start = int(''.join(map(str, num1_digits)))
        end = int(''.join(map(str, num2_digits)))

        if min_sum > max_sum:
            return 0

        if min_sum == max_sum:
            count = (end - start + 1) % MOD
            return count if count != 0 else 1

        good_count = count_good_integers(start, end)
        return good_count
